-- Duo 1 core market, coordination, and audit schema.
-- Money is stored as integer minor units in BIGINT columns.
-- All identifiers are UUIDs generated by the application, not PostgreSQL.
-- Timestamps are TIMESTAMPTZ and serialized as ISO 8601 UTC.

CREATE TABLE IF NOT EXISTS parties (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('buyer', 'provider', 'coordinator', 'platform')),
  name text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS provider_profiles (
  party_id uuid PRIMARY KEY REFERENCES parties(id) ON DELETE CASCADE,
  hardware jsonb NOT NULL DEFAULT '[]'::jsonb,
  allowed_workloads text[] NOT NULL DEFAULT '{}',
  regions text[] NOT NULL DEFAULT '{}',
  price_model jsonb NOT NULL DEFAULT '{}'::jsonb,
  authorized_at timestamptz,
  authorization_expires_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS provider_authorizations (
  id uuid PRIMARY KEY,
  provider_id uuid NOT NULL REFERENCES parties(id) ON DELETE CASCADE,
  scope jsonb NOT NULL DEFAULT '{}'::jsonb,
  authorized_at timestamptz NOT NULL,
  expires_at timestamptz,
  revoked_at timestamptz,
  evidence_ref text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS market_offers (
  id uuid PRIMARY KEY,
  provider_id uuid NOT NULL REFERENCES parties(id) ON DELETE CASCADE,
  source text NOT NULL CHECK (source IN ('worker', 'external_reference')),
  external_ref text,
  gpu_model text NOT NULL,
  gpu_count integer NOT NULL CHECK (gpu_count > 0),
  cpu_cores integer NOT NULL DEFAULT 0 CHECK (cpu_cores >= 0),
  memory_gb integer NOT NULL DEFAULT 0 CHECK (memory_gb >= 0),
  rate_minor_per_gpu_hour bigint NOT NULL CHECK (rate_minor_per_gpu_hour >= 0),
  currency char(3) NOT NULL DEFAULT 'USD',
  location text,
  available_from timestamptz,
  available_until timestamptz,
  observed_at timestamptz NOT NULL,
  expires_at timestamptz,
  executable boolean NOT NULL DEFAULT false,
  authorization_id uuid REFERENCES provider_authorizations(id),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (available_until IS NULL OR available_from IS NULL OR available_until > available_from)
);

CREATE INDEX IF NOT EXISTS market_offers_provider_idx ON market_offers (provider_id);
CREATE INDEX IF NOT EXISTS market_offers_gpu_rate_idx ON market_offers (gpu_model, rate_minor_per_gpu_hour);
CREATE INDEX IF NOT EXISTS market_offers_source_idx ON market_offers (source);
CREATE INDEX IF NOT EXISTS market_offers_expiry_idx ON market_offers (expires_at);
CREATE INDEX IF NOT EXISTS market_offers_observed_idx ON market_offers (observed_at DESC);

CREATE TABLE IF NOT EXISTS workloads (
  id uuid PRIMARY KEY,
  buyer_id uuid NOT NULL REFERENCES parties(id),
  type text NOT NULL,
  gpu_model text NOT NULL,
  gpu_count integer NOT NULL CHECK (gpu_count > 0),
  cpu_cores integer NOT NULL DEFAULT 0 CHECK (cpu_cores >= 0),
  memory_gb integer NOT NULL DEFAULT 0 CHECK (memory_gb >= 0),
  budget_minor bigint NOT NULL CHECK (budget_minor >= 0),
  deadline timestamptz,
  earliest_start timestamptz,
  flexibility jsonb NOT NULL DEFAULT '{}'::jsonb,
  state text NOT NULL DEFAULT 'open' CHECK (state IN ('draft', 'open', 'cleared', 'executing', 'complete', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (deadline IS NULL OR earliest_start IS NULL OR deadline > earliest_start)
);

CREATE INDEX IF NOT EXISTS workloads_buyer_idx ON workloads (buyer_id);
CREATE INDEX IF NOT EXISTS workloads_state_idx ON workloads (state);

CREATE TABLE IF NOT EXISTS commitments (
  id uuid PRIMARY KEY,
  workload_id uuid NOT NULL REFERENCES workloads(id) ON DELETE CASCADE,
  offer_id uuid NOT NULL REFERENCES market_offers(id),
  window_start timestamptz NOT NULL,
  window_end timestamptz NOT NULL,
  rights jsonb NOT NULL DEFAULT '{}'::jsonb,
  reservation_status text NOT NULL DEFAULT 'planned'
    CHECK (reservation_status IN ('planned', 'held', 'reserved', 'released', 'expired', 'failed')),
  expires_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (window_end > window_start)
);

CREATE INDEX IF NOT EXISTS commitments_workload_idx ON commitments (workload_id);
CREATE INDEX IF NOT EXISTS commitments_offer_idx ON commitments (offer_id);

CREATE TABLE IF NOT EXISTS reservations (
  id uuid PRIMARY KEY,
  offer_id uuid NOT NULL REFERENCES market_offers(id),
  commitment_id uuid REFERENCES commitments(id),
  status text NOT NULL CHECK (status IN ('held', 'reserved', 'released', 'expired', 'failed')),
  version integer NOT NULL DEFAULT 1,
  held_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  released_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS reservations_offer_status_idx ON reservations (offer_id, status);

CREATE TABLE IF NOT EXISTS deals (
  id uuid PRIMARY KEY,
  workload_id uuid NOT NULL REFERENCES workloads(id),
  title text,
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'awaiting_human_approval', 'approved', 'handoff_ready', 'rejected_by_participant', 'escalated', 'expired', 'failed')),
  current_version integer NOT NULL DEFAULT 0 CHECK (current_version >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS deals_workload_idx ON deals (workload_id);
CREATE INDEX IF NOT EXISTS deals_status_idx ON deals (status);

CREATE TABLE IF NOT EXISTS deal_versions (
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL CHECK (version > 0),
  status text NOT NULL DEFAULT 'proposed'
    CHECK (status IN ('proposed', 'awaiting_human_approval', 'approved', 'rejected_by_participant', 'superseded', 'handoff_ready', 'expired')),
  proposal jsonb NOT NULL,
  engine jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text,
  PRIMARY KEY (deal_id, version)
);

CREATE TABLE IF NOT EXISTS deal_approval_requests (
  id uuid PRIMARY KEY,
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL,
  participant_id uuid NOT NULL REFERENCES parties(id),
  obligation text NOT NULL,
  amount_minor bigint NOT NULL DEFAULT 0 CHECK (amount_minor >= 0),
  currency char(3) NOT NULL DEFAULT 'USD',
  channel text NOT NULL DEFAULT 'api',
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'expired', 'superseded')),
  expires_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (deal_id, version, participant_id),
  FOREIGN KEY (deal_id, version) REFERENCES deal_versions(deal_id, version) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS approval_requests_deal_idx ON deal_approval_requests (deal_id, version);
CREATE INDEX IF NOT EXISTS approval_requests_party_idx ON deal_approval_requests (participant_id, status);

CREATE TABLE IF NOT EXISTS approvals (
  id uuid PRIMARY KEY,
  request_id uuid NOT NULL UNIQUE REFERENCES deal_approval_requests(id) ON DELETE CASCADE,
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL,
  participant_id uuid NOT NULL REFERENCES parties(id),
  decision text NOT NULL CHECK (decision IN ('approved', 'rejected')),
  attested_by text NOT NULL,
  attestation_channel text NOT NULL DEFAULT 'api',
  simulated boolean NOT NULL DEFAULT false,
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (deal_id, version) REFERENCES deal_versions(deal_id, version) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS approvals_deal_version_idx ON approvals (deal_id, version);

CREATE TABLE IF NOT EXISTS negotiation_events (
  id uuid PRIMARY KEY,
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL,
  round integer NOT NULL DEFAULT 1 CHECK (round > 0),
  event_type text NOT NULL,
  actor_id text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (deal_id, version) REFERENCES deal_versions(deal_id, version) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS negotiation_events_deal_idx ON negotiation_events (deal_id, version, created_at);

CREATE TABLE IF NOT EXISTS escalations (
  id uuid PRIMARY KEY,
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL,
  reason text NOT NULL,
  details jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'dismissed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz
);

CREATE INDEX IF NOT EXISTS escalations_deal_idx ON escalations (deal_id, created_at DESC);

CREATE TABLE IF NOT EXISTS handoffs (
  id uuid PRIMARY KEY,
  deal_id uuid NOT NULL REFERENCES deals(id) ON DELETE CASCADE,
  version integer NOT NULL,
  status text NOT NULL CHECK (status IN ('provisional', 'committed', 'cancelled', 'failed')),
  reservation_status text NOT NULL CHECK (reservation_status IN ('not_reserved', 'held', 'reserved', 'conflict')),
  settlement_authorized boolean NOT NULL DEFAULT false CHECK (settlement_authorized = false),
  package jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (deal_id, version)
);

CREATE TABLE IF NOT EXISTS human_users (
  id uuid PRIMARY KEY,
  display_name text NOT NULL,
  email text UNIQUE,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS api_keys (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  key_hash text NOT NULL UNIQUE,
  role text NOT NULL CHECK (role IN ('agent', 'human', 'finance', 'admin', 'worker')),
  party_id uuid REFERENCES parties(id),
  human_user_id uuid REFERENCES human_users(id),
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz,
  last_used_at timestamptz,
  CHECK (role <> 'human' OR human_user_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS api_keys_hash_idx ON api_keys (key_hash) WHERE active;

CREATE TABLE IF NOT EXISTS idempotency_keys (
  principal_id text NOT NULL,
  idempotency_key text NOT NULL,
  method text NOT NULL,
  path text NOT NULL,
  request_hash text NOT NULL,
  state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'completed')),
  status_code integer,
  response_body jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (principal_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idempotency_expiry_idx ON idempotency_keys (expires_at);

CREATE TABLE IF NOT EXISTS audit_events (
  id bigserial PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  actor_id text NOT NULL,
  actor_role text NOT NULL,
  action text NOT NULL,
  object_type text NOT NULL,
  object_id text NOT NULL,
  deal_id uuid,
  idempotency_key text,
  before_state jsonb,
  after_state jsonb,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS audit_events_object_idx ON audit_events (object_type, object_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_events_deal_idx ON audit_events (deal_id, occurred_at DESC);

CREATE TABLE IF NOT EXISTS agent_work_items (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('deal_opportunity', 'financial_exception', 'approval_followup')),
  deal_id uuid REFERENCES deals(id),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'claimed', 'completed', 'failed')),
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  claimed_at timestamptz,
  completed_at timestamptz
);

CREATE INDEX IF NOT EXISTS agent_work_items_status_idx ON agent_work_items (status, created_at);

CREATE TABLE IF NOT EXISTS outbox (
  id bigserial PRIMARY KEY,
  topic text NOT NULL,
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz
);

CREATE INDEX IF NOT EXISTS outbox_unpublished_idx ON outbox (published_at) WHERE published_at IS NULL;

-- Time-series source tables. On Tiger Data, 0003 converts these to hypertables.
CREATE TABLE IF NOT EXISTS market_observations (
  id bigserial NOT NULL,
  observed_at timestamptz NOT NULL,
  offer_id uuid,
  provider_id uuid,
  gpu_model text NOT NULL,
  rate_minor_per_gpu_hour bigint NOT NULL CHECK (rate_minor_per_gpu_hour >= 0),
  source text NOT NULL,
  currency char(3) NOT NULL DEFAULT 'USD',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (id, observed_at)
);

CREATE INDEX IF NOT EXISTS market_observations_time_idx ON market_observations (observed_at DESC);
CREATE INDEX IF NOT EXISTS market_observations_gpu_time_idx ON market_observations (gpu_model, observed_at DESC);

CREATE TABLE IF NOT EXISTS execution_events (
  id uuid PRIMARY KEY,
  workload_id uuid NOT NULL REFERENCES workloads(id),
  job_id text,
  worker_id text,
  event_type text NOT NULL,
  measured_at timestamptz NOT NULL,
  gpu_seconds numeric(18, 3),
  proof_reference text,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS execution_events_workload_idx ON execution_events (workload_id, measured_at DESC);
